const form = $('On Application Submission').first().json;
const resumeText = String($('Extract Resume Text').first().json.text ?? '').trim();
const rows = $input.all().map(x => x.json || {});
const name = String(form.Name ?? '').trim();
const email = String(form.Email ?? '').trim().toLowerCase();
const phone = String(form['Phone Number'] ?? '').trim();
const roleTitle = String(form['Role Title'] ?? '').trim();
const jobId = String(form['Job ID'] ?? '').trim();
const jobDescription = String(form['Job Description'] ?? '').trim();

if (!name || !email || !phone || !roleTitle || !jobId || !jobDescription) {
  throw new Error('Required application fields are missing.');
}
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  throw new Error('The submitted email address is invalid.');
}
if (!resumeText || resumeText.length < 40) {
  throw new Error('The PDF contains too little readable text. Ask the applicant to upload a text-based PDF.');
}
if (resumeText.length > 50000) {
  throw new Error('The extracted resume is unusually long. Review the file manually before processing.');
}

const existing = rows.filter(r => String(r.Email ?? '').trim().toLowerCase() === email
  && String(r['Job ID'] ?? '').trim().toLowerCase() === jobId.toLowerCase());
const duplicate = existing.length > 0;
const duplicateOf = duplicate ? String(existing[0]['Candidate ID'] ?? '') : '';
const now = new Date().toISOString();
const candidateId = `CAND-${now.slice(0,10).replace(/-/g,'')}-${Math.random().toString(36).slice(2,8).toUpperCase()}`;

return [{
  json: {
    'Candidate ID': candidateId,
    Name: name,
    Email: email,
    'Phone Number': phone,
    'Role Title': roleTitle,
    'Job ID': jobId,
    'Job Description': jobDescription,
    ResumeText: resumeText,
    'Submitted At': now,
    'Last Updated': now,
    'Potential Duplicate': duplicate ? 'YES' : 'NO',
    'Duplicate Of Candidate ID': duplicateOf,
    Status: duplicate ? 'Potential Duplicate - Manual Review' : 'Pending Human Review',
    'AI Decision': 'ADVISORY ONLY - HUMAN REVIEW REQUIRED'
  }
}];

