const raw = String($json.output?.[0]?.content?.[0]?.text ?? $json.text ?? '').trim();
if (!raw) throw new Error('AI assessment returned an empty response.');
const cleaned = raw.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/i,'').trim();
let a;
try { a = JSON.parse(cleaned); }
catch {
  const start = cleaned.indexOf('{'), end = cleaned.lastIndexOf('}');
  if (start < 0 || end <= start) throw new Error('AI assessment was not valid JSON.');
  a = JSON.parse(cleaned.slice(start,end+1));
}
const base = $('Validate, Create ID & Detect Duplicates').first().json;
const rating = (v,k) => {
  const n = Number(v);
  if (!Number.isInteger(n) || n < 0 || n > 5) throw new Error(`Invalid ${k}: expected integer 0-5.`);
  return n;
};
const r1 = rating(a.essentialSkillsRating,'essentialSkillsRating');
const r2 = rating(a.relevantExperienceRating,'relevantExperienceRating');
const r3 = rating(a.roleQualificationsRating,'roleQualificationsRating');
const r4 = rating(a.evidenceQualityRating,'evidenceQualityRating');
const r5 = rating(a.preferredSkillsRating,'preferredSkillsRating');
const confidence = Number(a.confidence);
if (!Number.isInteger(confidence) || confidence < 0 || confidence > 100) throw new Error('AI confidence must be an integer 0-100.');
const arr = v => Array.isArray(v) ? v.map(x => String(x).trim()).filter(Boolean) : [];
const score = Math.round((r1*0.35 + r2*0.25 + r3*0.20 + r4*0.10 + r5*0.10) * 20);
return [{
 json: {
  'Candidate ID':base['Candidate ID'], Name:base.Name, Email:base.Email,
  'Phone Number':base['Phone Number'], 'Role Title':base['Role Title'], 'Job ID':base['Job ID'],
  'Assessment Summary':String(a.summary ?? '').trim(),
  'Match Score':score,
  'Essential Skills Rating':r1,'Relevant Experience Rating':r2,
  'Role Qualifications Rating':r3,'Evidence Quality Rating':r4,'Preferred Skills Rating':r5,
  Strengths:arr(a.strengths).join(' | '),
  'Skills Evidence':arr(a.skillsEvidence).join(' | '),
  'Relevant Gaps':arr(a.relevantGaps).join(' | '),
  'Missing Evidence':arr(a.missingEvidence).join(' | '),
  'AI Confidence':confidence,
  'Potential Duplicate':base['Potential Duplicate'],
  'Duplicate Of Candidate ID':base['Duplicate Of Candidate ID'],
  'AI Decision':'ADVISORY ONLY - HUMAN REVIEW REQUIRED',
  Status:base.Status,
  'Submitted At':base['Submitted At'],
  'Last Updated':new Date().toISOString(),
  Reviewer:'',
  'Review Decision':'',
  'Review Notes':'',
  'Job Description':base['Job Description']
 }
}];
